// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockTime) public {
        // Bound the fuzz parameters to avoid overflow/revert
        vm.assume(value == 10 ether); // fallback only accepts exactly 10 ether
        vm.assume(blockTime > c.pastBlockTime()); // ensures block.timestamp > pastBlockTime
        vm.warp(blockTime);

        // Record timestamp before call
        uint256 before = block.timestamp;

        // Call fallback with value
        (bool success, ) = address(c).call{value: value}("");

        // If the call succeeded, pastBlockTime must have been updated
        if (success) {
            assertTrue(c.pastBlockTime() == before);
        }
    }
}

